// Hand-written `fastify` stub for the flowatlas fixture suite.
//
// Fastify ships its own types, so there is one package rather than a `@types`
// one beside it. Only the shapes the reader matches on exist: the verb methods,
// the object form of a route, the plugin registration that carries a prefix,
// and the hook that installs something in front of everything.

export interface FastifyRequest<Body = unknown> {
  params: Record<string, string>;
  query: Record<string, string>;
  body: Body;
  headers: Record<string, string | undefined>;
}

export interface FastifyReply {
  code(status: number): FastifyReply;
  send(payload?: unknown): FastifyReply;
}

export type RouteHandler = (request: FastifyRequest<any>, reply: FastifyReply) => unknown;

export type HookHandler = (request: FastifyRequest<any>, reply: FastifyReply) => unknown;

export interface RouteShorthandOptions {
  preHandler?: RouteHandler | RouteHandler[];
  onRequest?: RouteHandler | RouteHandler[];
  schema?: unknown;
}

export interface RouteOptions extends RouteShorthandOptions {
  method: string | string[];
  url: string;
  handler: RouteHandler;
}

export interface RegisterOptions {
  prefix?: string;
}

export interface FastifyInstance {
  get(path: string, handler: RouteHandler): FastifyInstance;
  get(path: string, options: RouteShorthandOptions, handler: RouteHandler): FastifyInstance;
  post(path: string, handler: RouteHandler): FastifyInstance;
  post(path: string, options: RouteShorthandOptions, handler: RouteHandler): FastifyInstance;
  put(path: string, handler: RouteHandler): FastifyInstance;
  put(path: string, options: RouteShorthandOptions, handler: RouteHandler): FastifyInstance;
  patch(path: string, handler: RouteHandler): FastifyInstance;
  delete(path: string, handler: RouteHandler): FastifyInstance;
  delete(path: string, options: RouteShorthandOptions, handler: RouteHandler): FastifyInstance;
  options(path: string, handler: RouteHandler): FastifyInstance;
  head(path: string, handler: RouteHandler): FastifyInstance;
  all(path: string, handler: RouteHandler): FastifyInstance;
  route(options: RouteOptions): FastifyInstance;
  register(plugin: FastifyPluginAsync, options?: RegisterOptions): FastifyInstance;
  addHook(name: string, hook: HookHandler): FastifyInstance;
  listen(options: { port: number }): Promise<string>;
}

export type FastifyPluginAsync = (instance: FastifyInstance, options: unknown) => Promise<void>;

declare function fastify(options?: { logger?: boolean }): FastifyInstance;

export default fastify;
